using System;using SarmatVisionHold.KestrelClient.Models;using SarmatVisionHold.Vision;
namespace SarmatVisionHold.KestrelClient.Processing { public sealed class MotionValidator { readonly double minimumQuality;public MotionValidator(double minimumQuality=.35){this.minimumQuality=minimumQuality;}public ValidationResult Validate(SparseOpticalFlowResult flow,MotionDecision detected,GroundTruthMotion expected){var r=new ValidationResult{Expected=expected,Detected=detected};if(flow==null||expected==null||expected.Classification==ExpectedMotion.Unknown||flow.Quality<minimumQuality||flow.Status!=FlowTrackingStatus.OK){r.Status=ValidationStatus.UNKNOWN;r.Reason="Insufficient ground truth or optical-flow quality";return r;}var actual=Kind(detected.SmoothedClass);if(actual!=expected.Classification){r.Status=ValidationStatus.FAIL;r.Reason=$"Expected {expected.Classification}, detected {actual}";return r;}if(actual==ExpectedMotion.Translating||actual==ExpectedMotion.Mixed){if(detected.TextureMotion==expected.TextureDirection){r.Status=ValidationStatus.PASS;r.Reason="Motion class and texture direction agree";}else{r.Status=ValidationStatus.PARTIAL;r.Reason="Motion class agrees but direction differs";}return r;}if(actual==ExpectedMotion.Rotating||actual==ExpectedMotion.Mixed){var rotation=flow.RotationDegrees>0?"CCW":"CW";r.Status=rotation==expected.RotationDirection?ValidationStatus.PASS:ValidationStatus.PARTIAL;r.Reason="Rotation comparison";return r;}r.Status=ValidationStatus.PASS;r.Reason="Motion class agrees";return r;}static ExpectedMotion Kind(string s){if(s=="STILL")return ExpectedMotion.Still;if(s!=null&&s.StartsWith("TRANSLATING"))return ExpectedMotion.Translating;if(s!=null&&s.StartsWith("ROTATING"))return ExpectedMotion.Rotating;if(s=="MIXED")return ExpectedMotion.Mixed;return ExpectedMotion.Unknown;} } }
